/* ==============================================================
   Objeto ..........: dbo.BI_QUALIDADE
   Tipo ............: VIEW
   Criado em .......: 2015-11-09 11:41:34
   Modificado em ...: 2016-03-22 19:20:04
   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: GE_PESSOA, IV_ACAO, IV_CLASSERES, IV_HISTORICO, IV_RESCLASSE, IV_RESULTADO, IVS_CARTEIRA, IVS_PES
   Outras refs .....: IV_Q$QUALIDADE_PECAS, IV_Q$QUALIDADE_SERVICOS, IV_Q$QUALIDADE_VENDAMAQ
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

CREATE VIEW BI_QUALIDADE AS  SELECT HIS.DTAREALIZACAO,          HIS.SEQPESSOA,         PES.NomeRazao,         CRT.Carteira,         HIS.PROCESSO,          ACA.DESCRICAO AS ACAO,          'Peças' AS AREA,                     CLAS.Classe AS CLASSE,         RES.DESCRICAO AS RESULTADO,         PCA.SATISFEITO_ATEND AS SATISFACAO_ATENDIMENTO,         PCA.MOTIVO AS MOTIVO_INSATISFACAO,         CASE PCA.INDICARIA   	                WHEN 10 THEN 'Nota 10'        	    	    WHEN 9 THEN 'Nota 9'                      WHEN 8 THEN 'Nota 8'       	 	        WHEN 7 THEN 'Nota 7'                      WHEN 6 THEN 'Nota 6'  		            WHEN 5 THEN 'Nota 5'  		            WHEN 4 THEN 'Nota 4'  		            WHEN 3 THEN 'Nota 3'  		            WHEN 2 THEN 'Nota 2'                      WHEN 1 THEN 'Nota 1'  	                WHEN 0 THEN 'Nota 0'		                                 END AS NOTA,     	                CASE PCA.INDICARIA   	                WHEN 10 THEN 'Promotor'        	    	    WHEN 9 THEN 'Promotor'                       WHEN 8 THEN 'Neutro'        	 	        WHEN 7 THEN 'Neutro'                       WHEN 6 THEN 'Depreciador'    		            WHEN 5 THEN 'Depreciador'    		            WHEN 4 THEN 'Depreciador'    		            WHEN 3 THEN 'Depreciador'    		            WHEN 2 THEN 'Depreciador'                        WHEN 1 THEN 'Depreciador'   	                WHEN 0 THEN 'Depreciador' 		                                 END AS PROMOTOR,                PCA.PRECISA_FAZER AS DETALHE_FRM	    FROM IV_HISTORICO HIS  JOIN IV_Q$QUALIDADE_PECAS PCA ON PCA.PROCESSO = HIS.Processo  JOIN GE_PESSOA PES ON PES.SeqPessoa = PCA.SeqPessoa  JOIN IVS_PES PESC ON PESC.SeqPessoa = PES.SeqPessoa  JOIN IVS_CARTEIRA CRT ON CRT.SeqCarteira = PESC.SeqCarteira  LEFT JOIN IV_RESULTADO RES ON RES.RESULTADO = HIS.RESULTADO  LEFT JOIN IV_RESCLASSE RESC ON RESC.Resultado = RES.Resultado  LEFT JOIN IV_CLASSERES CLAS ON CLAS.SeqClasseRes = RESC.SeqClasseRes  LEFT JOIN IV_ACAO ACA ON ACA.ACAO = HIS.ACAOGERADORA  WHERE HIS.AcaoGeradora = 940030     AND RESC.SeqClasseRes IN (9,10)   UNION  SELECT HIS.DTAREALIZACAO,          HIS.SEQPESSOA,         PES.NomeRazao,         CRT.Carteira,         HIS.PROCESSO,          ACA.DESCRICAO AS ACAO,          'Serviços' AS AREA,                     CLAS.Classe AS CLASSE,         RES.DESCRICAO AS RESULTADO,         PCA.SATISFEITO_ATEND AS SATISFACAO_ATENDIMENTO,         PCA.MOTIVO AS MOTIVO_INSATISFACAO,         CASE PCA.INDICARIA   	                WHEN 10 THEN 'Nota 10'        	    	    WHEN 9 THEN 'Nota 9'                      WHEN 8 THEN 'Nota 8'       	 	        WHEN 7 THEN 'Nota 7'                      WHEN 6 THEN 'Nota 6'  		            WHEN 5 THEN 'Nota 5'  		            WHEN 4 THEN 'Nota 4'  		            WHEN 3 THEN 'Nota 3'  		            WHEN 2 THEN 'Nota 2'                      WHEN 1 THEN 'Nota 1'  	                WHEN 0 THEN 'Nota 0'		                                 END AS NOTA,     	                CASE PCA.INDICARIA   	                WHEN 10 THEN 'Promotor'        	    	    WHEN 9 THEN 'Promotor'                       WHEN 8 THEN 'Neutro'        	 	        WHEN 7 THEN 'Neutro'                       WHEN 6 THEN 'Depreciador'    		            WHEN 5 THEN 'Depreciador'    		            WHEN 4 THEN 'Depreciador'    		            WHEN 3 THEN 'Depreciador'    		            WHEN 2 THEN 'Depreciador'                        WHEN 1 THEN 'Depreciador'   	                WHEN 0 THEN 'Depreciador' 		                                 END AS PROMOTOR,                PCA.PRECISA_FAZER AS DETALHE_FRM	    FROM IV_HISTORICO HIS  JOIN IV_Q$QUALIDADE_SERVICOS PCA ON PCA.PROCESSO = HIS.Processo  JOIN GE_PESSOA PES ON PES.SeqPessoa = PCA.SeqPessoa  JOIN IVS_PES PESC ON PESC.SeqPessoa = PES.SeqPessoa  JOIN IVS_CARTEIRA CRT ON CRT.SeqCarteira = PESC.SeqCarteira  LEFT JOIN IV_RESULTADO RES ON RES.RESULTADO = HIS.RESULTADO  LEFT JOIN IV_RESCLASSE RESC ON RESC.Resultado = RES.Resultado  LEFT JOIN IV_CLASSERES CLAS ON CLAS.SeqClasseRes = RESC.SeqClasseRes  LEFT JOIN IV_ACAO ACA ON ACA.ACAO = HIS.ACAOGERADORA  WHERE HIS.AcaoGeradora = 940027     AND RESC.SeqClasseRes IN (9,10)           UNION  SELECT HIS.DTAREALIZACAO,          HIS.SEQPESSOA,         PES.NomeRazao,         CRT.Carteira,         HIS.PROCESSO,          ACA.DESCRICAO AS ACAO,          'Vendas' AS AREA,                     CLAS.Classe AS CLASSE,         RES.DESCRICAO AS RESULTADO,         PCA.SATISFEITO_ATEND AS SATISFACAO_ATENDIMENTO,         PCA.MOTIVO AS MOTIVO_INSATISFACAO,         CASE PCA.INDICARIA   	                WHEN 10 THEN 'Nota 10'        	    	    WHEN 9 THEN 'Nota 9'                      WHEN 8 THEN 'Nota 8'       	 	        WHEN 7 THEN 'Nota 7'                      WHEN 6 THEN 'Nota 6'  		            WHEN 5 THEN 'Nota 5'  		            WHEN 4 THEN 'Nota 4'  		            WHEN 3 THEN 'Nota 3'  		            WHEN 2 THEN 'Nota 2'                      WHEN 1 THEN 'Nota 1'  	                WHEN 0 THEN 'Nota 0'		                                 END AS NOTA,     	                CASE PCA.INDICARIA   	                WHEN 10 THEN 'Promotor'        	    	    WHEN 9 THEN 'Promotor'                       WHEN 8 THEN 'Neutro'        	 	        WHEN 7 THEN 'Neutro'                       WHEN 6 THEN 'Depreciador'    		            WHEN 5 THEN 'Depreciador'    		            WHEN 4 THEN 'Depreciador'    		            WHEN 3 THEN 'Depreciador'    		            WHEN 2 THEN 'Depreciador'                        WHEN 1 THEN 'Depreciador'   	                WHEN 0 THEN 'Depreciador' 		                                 END AS PROMOTOR,                PCA.PRECISA_FAZER AS DETALHE_FRM	    FROM IV_HISTORICO HIS  JOIN IV_Q$QUALIDADE_VENDAMAQ PCA ON PCA.PROCESSO = HIS.Processo  JOIN GE_PESSOA PES ON PES.SeqPessoa = PCA.SeqPessoa  JOIN IVS_PES PESC ON PESC.SeqPessoa = PES.SeqPessoa  JOIN IVS_CARTEIRA CRT ON CRT.SeqCarteira = PESC.SeqCarteira  LEFT JOIN IV_RESULTADO RES ON RES.RESULTADO = HIS.RESULTADO  LEFT JOIN IV_RESCLASSE RESC ON RESC.Resultado = RES.Resultado  LEFT JOIN IV_CLASSERES CLAS ON CLAS.SeqClasseRes = RESC.SeqClasseRes  LEFT JOIN IV_ACAO ACA ON ACA.ACAO = HIS.ACAOGERADORA  WHERE HIS.AcaoGeradora = 63     AND RESC.SeqClasseRes IN (9,10)     